private fun icon(name: String, autoMirror: Boolean, vararg paths: String): ImageVector =
    ImageVector.Builder(
        name = "Rounded.$name",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror,
    ).apply {
        paths.forEach { addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) }
    }.build()

